using Avalonia;
using Avalonia.Media;
using Avalonia.Media.Imaging;
using Avalonia.Platform;
using RetroHub.Core.Logging;

namespace RetroHub.App.Theming;

/// <summary>
/// One shared tiling <see cref="ImageBrush"/> per era texture (DESIGN 4.5: "Pro Textur gibt es eine Brush-Instanz,
/// nie eine pro Kachel"). The PNGs are generated by build/tools/texturegen.py into Assets/Textures.
/// The brush tiles at 1 unit = 1 texture pixel; <see cref="Controls.TextureFill"/> scales it to whole device pixels.
/// </summary>
public static class TextureBrushes
{
    private static readonly Dictionary<Texture, (ImageBrush Brush, PixelSize Size)?> Cache = new();

    public static (ImageBrush Brush, PixelSize Size)? Get(Texture texture)
    {
        if (texture == Texture.None) return null;
        lock (Cache)
        {
            if (Cache.TryGetValue(texture, out var hit)) return hit;
            (ImageBrush, PixelSize)? made = null;
            try
            {
                var file = Textures.FileName(texture);
                if (file != null)
                {
                    using var stream = AssetLoader.Open(new Uri("avares://RetroHub.App/Assets/Textures/" + file));
                    var bitmap = new Bitmap(stream);
                    var size = bitmap.PixelSize;
                    var brush = new ImageBrush(bitmap)
                    {
                        TileMode = TileMode.Tile,
                        Stretch = Stretch.None,
                        AlignmentX = AlignmentX.Left,
                        AlignmentY = AlignmentY.Top,
                        DestinationRect = new RelativeRect(0, 0, size.Width, size.Height, RelativeUnit.Absolute),
                    };
                    made = (brush, size);
                }
            }
            catch (Exception ex) { Log.Warn($"Texture {texture} could not be loaded", ex); }
            Cache[texture] = made;
            return made;
        }
    }
}
